api.look('paper');
const cx = api.w/2, cy = 330, k = api.seg(t, 0, 1.4);
api.circle(cx, cy, 150, {c:'a2', w:4, k, fill:'a2', a:0.15});
api.ellipse(cx, cy, 150, 50, {c:'a2', w:2, k:api.seg(t,0.3,1.6), a:0.6});
api.arc(cx, cy, 150, 1.57, 4.71, {c:'a2', w:2, k:api.seg(t,0.4,1.7), a:0.6});
api.kinetic('8.2 billion', cx, 560, {mode:'rise', k:api.seg(t,1,2.2), size:40, t});
api.text('people on Earth', cx, 610, {size:20, c:'dim', align:'center', k:api.seg(t,1.8,2.8)});
api.say('Eight billion people, six continents', 0.3, 3.3);

api.look('paper');
const d = [
 {label:'Asia', v:4.8, c:'accent'},
 {label:'Africa', v:1.5, c:'a3'},
 {label:'Europe', v:0.74, c:'a2'},
 {label:'N. America', v:0.6, c:'a2'},
 {label:'S. America', v:0.44, c:'a2'},
 {label:'Oceania', v:0.05, c:'a2'}
];
api.text('People by continent (billions)', api.w/2, 90, {size:24, weight:'bold', align:'center', k:api.seg(t,0,0.8)});
api.bars(d, 30, 130, api.w-60, 520, {k:api.ease(api.seg(t,0.5,3.5))});
api.callout('Asia: 4.8 billion', 200, 190, 250, 700, {k:api.seg(t,3.5,4.8), c:'accent'});
api.say('Asia holds well over half', 0.4, 5.5);

api.look('paper');
api.text('Growth per year', api.w/2, 90, {size:28, weight:'bold', align:'center', k:api.seg(t,0,0.8)});
const d = [
 {label:'Africa', v:2.4, c:'accent'},
 {label:'Oceania', v:1.3, c:'a3'},
 {label:'S. America', v:0.6, c:'a2'},
 {label:'N. America', v:0.5, c:'a2'},
 {label:'Asia', v:0.4, c:'a2'},
 {label:'Europe', v:0.0, c:'a2'}
];
api.bars(d, 30, 130, api.w-60, 520, {k:api.ease(api.seg(t,0.4,3.2))});
api.scribble(api.w/2, 190, 170, 40, {k:api.seg(t,3.2,4.4), c:'bad'});
api.counter(2.4, api.w/2, 720, {k:api.seg(t,3.4,5), suf:'% a year', d:1, size:44, c:'accent'});
api.say('Africa grows fastest, 2.4% a year', 0.4, 5.5);

api.look('paper');
const cx = api.w/2, cy = 330;
const p = api.shape('star', cx, cy, 10, {c:'accent'});
api.path('M-60 -110 L10 -120 L70 -70 L90 0 L60 70 L30 140 L-10 150 L-40 80 L-80 20 L-100 -50 Z', {x:cx, y:cy, s:1.5, c:'accent', w:4, fill:'accent', a:0.9, k:api.seg(t,0,1.5)});
const n = api.lerp(1.5, 2.5, api.ease(api.seg(t,1.5,5)));
api.counter(n, cx, 640, {pre:'', suf:' billion', d:1, size:44, k:api.seg(t,1.2,2)});
api.text('by 2050', cx, 690, {size:22, c:'dim', align:'center', k:api.seg(t,3,4)});
api.swarm(60, t, {mode:'rise', cx, cy:cy+40, rx:90, ry:130, c:'accent', size:3});
api.focus(cx, cy, api.lerp(1, 1.15, api.ease(api.seg(t,0,6))));
api.say('Africa nears 2.5 billion by 2050', 0.4, 5.5);
